function AuthModal({visible,onClose,onAuth}){const[mode,setMode]=useState('login');const[name,setName]=useState('');const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[err,setErr]=useState('');const[busy,setBusy]=useState(false);async function submit(){setBusy(true);setErr('');try{const d=await api(`/api/auth/${mode}`,{method:'POST',body:JSON.stringify(mode==='register'?{name,email,password}:{email,password})});await tokenSet(d.token);onAuth(d.user);onClose()}catch(e){setErr(e.message)}finally{setBusy(false)}}return <Modal visible={visible} transparent animationType="fade"><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.modalShade}><View style={styles.authCard}><Logo/><Text style={styles.authTitle}>{mode==='login'?'Welcome back':'Create your Ripple account'}</Text>{mode==='register'?<TextInput value={name} onChangeText={setName} placeholder="Name" placeholderTextColor="#68727c" style={styles.input}/>:null}<TextInput value={email} onChangeText={setEmail} placeholder="Email" placeholderTextColor="#68727c" style={styles.input} autoCapitalize="none"/><TextInput value={password} onChangeText={setPassword} placeholder="Password" placeholderTextColor="#68727c" style={styles.input} secureTextEntry/>{err?<Text style={styles.error}>{err}</Text>:null}<Button onPress={submit}>{busy?'Please wait…':mode==='login'?'Sign in':'Create account'}</Button><Pressable onPress={()=>setMode(mode==='login'?'register':'login')}><Text style={styles.switch}>{mode==='login'?'New to Ripple? Create account':'Already have an account? Sign in'}</Text></Pressable><Pressable onPress={onClose}><Text style={styles.cancel}>Cancel</Text></Pressable></View></ScrollView></Modal>}

let hlsLoader;
function loadHlsJs(){
 if(globalThis.Hls)return Promise.resolve(globalThis.Hls);
 if(hlsLoader)return hlsLoader;
 hlsLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/hls.js@1.6.13/dist/hls.min.js';script.crossOrigin='anonymous';script.onload=()=>resolve(globalThis.Hls);script.onerror=()=>reject(new Error('HLS playback support could not be loaded.'));document.head.appendChild(script)});
 return hlsLoader;
}


function PlaybackNotice({notice,onClose,onRetry}){if(!notice)return null;const pending=notice.kind==='pending',loading=notice.kind==='loading',network=notice.kind==='network';return <Modal visible transparent animationType="fade" onRequestClose={onClose}><View style={styles.modalShade}><View accessibilityRole={loading?undefined:'alert'} accessibilityLiveRegion="polite" style={styles.authCard}>{loading?<ActivityIndicator color={C.copper}/>:null}<Text style={styles.playerStatusTitle}>{loading?'Preparing video':pending?'Coming Soon':network?'Service unavailable':'Video unavailable'}</Text><Text style={styles.playerStatusText}>{loading?`Requesting secure playback for ${notice.title}…`:pending?'This mythology-inspired title is still being prepared. Please check back soon.':network?(notice.message||'Ripple could not reach the playback service. Please try again.'):'This title does not have playable media yet.'}</Text>{network?<Button small onPress={onRetry}>Retry</Button>:null}{!loading?<Button small outline onPress={onClose}>Close</Button>:null}</View></View></Modal>}

function Player({item,onClose,onProgress,onAction}){
 const {width}=useWindowDimensions();const {phone}=getResponsiveState(width);const[state,setState]=useState('loading');const[error,setError]=useState('');const videoRef=useRef(null);const hlsRef=useRef(null);const lastProgress=useRef(-1);const videoUrl=item?.videoUrl;const poster=resolveWebPoster(item?.image);const hls=isHlsUrl(videoUrl,item?.mimeType);
 const attach=useCallback(async()=>{const video=videoRef.current;if(!video||!videoUrl)return;setState('loading');setError('');try{if(hls&&!video.canPlayType('application/vnd.apple.mpegurl')){const Hls=await loadHlsJs();if(!Hls?.isSupported())throw new Error('This browser cannot play this HLS stream.');const engine=new Hls({enableWorker:true});hlsRef.current=engine;engine.on(Hls.Events.ERROR,(_event,data)=>{if(data.fatal){setError('The video stream was interrupted.');setState('error')}});engine.loadSource(videoUrl);engine.attachMedia(video)}else{video.src=videoUrl}video.load()}catch(e){setError(e.message);setState('error')}},[videoUrl,hls]);
 useEffect(()=>{attach();return()=>{const video=videoRef.current;if(video){video.pause();video.removeAttribute('src');video.load()}hlsRef.current?.destroy();hlsRef.current=null}},[attach]);
 if(!item)return null;const close=()=>{videoRef.current?.pause();onClose()};
 const details=<><Text style={styles.eyebrow}>{item.category||item.type||'RIPPLE TITLE'}</Text><Text accessibilityRole="header" style={[styles.playerTitle,phone&&styles.playerTitlePhone]}>{item.title}</Text><Text style={styles.playerCreator}>Created by {creatorName(item)}</Text>{item.description?<Text style={styles.playerDesc}>{item.description}</Text>:null}<Text style={styles.metaLight}>{[item.language,item.subtitles&&`${item.subtitles} subtitles`,item.duration,item.rating,item.year].filter(Boolean).join('  •  ')}</Text><View style={styles.inlineActions}><Button small outline onPress={()=>onAction?.('like',item)}>♡ Like</Button><Button small outline onPress={()=>onAction?.('share',item)}>Share</Button><Button small outline onPress={()=>onAction?.('report',item)}>Report content</Button></View></>;
 return <Modal visible animationType="fade" onRequestClose={close}><SafeAreaView style={styles.player}><View style={[styles.playerTop,phone&&styles.playerTopPhone]}><Logo/><Button small outline onPress={close}>Close</Button></View><ScrollView contentContainerStyle={[styles.playerBody,phone&&styles.playerBodyPhone]}><View style={styles.videoFrame}><video key={item.backendContentId||item.id} ref={videoRef} poster={poster||undefined} aria-label={`${item.title} video player`} controls playsInline preload="metadata" tabIndex="0" onCanPlay={()=>setState('ready')} onWaiting={()=>setState('loading')} onPlaying={()=>setState('ready')} onEnded={()=>onProgress?.(item,1)} onTimeUpdate={e=>{const v=e.currentTarget,second=Math.floor(v.currentTime);if(v.duration&&second-lastProgress.current>=5){lastProgress.current=second;onProgress?.(item,v.currentTime/v.duration)}}} onError={()=>{setError('The video could not be loaded. Check your connection and try again.');setState('error')}} style={{display:'block',width:'100%',aspectRatio:'16 / 9',objectFit:'contain',background:'#000',borderRadius:16}}>{(item.captions||item.subtitlesTracks||[]).map((track,index)=><track key={track.src||index} kind={track.kind||'subtitles'} src={track.src} srcLang={track.language||track.srcLang||'en'} label={track.label||track.language||'Subtitles'} default={track.default}/>)}</video>{state==='loading'?<View accessibilityLiveRegion="polite" style={styles.playerLoading}><ActivityIndicator color={C.copper}/><Text style={styles.playerStatusText}>Loading video…</Text></View>:null}{state==='error'?<View accessibilityRole="alert" style={styles.playerLoading}><Text style={styles.playerStatusTitle}>Video unavailable</Text><Text style={styles.playerStatusText}>{error}</Text><Button small onPress={attach}>Retry</Button></View>:null}</View>{details}</ScrollView></SafeAreaView></Modal>
}

function CreatorUpload({user,onRequireAuth}){
 const[form,setForm]=useState({title:'',description:'',aiDisclosure:'',language:'',category:'',rights:false});const[video,setVideo]=useState(null);const[thumbnail,setThumbnail]=useState(null);const[progress,setProgress]=useState(0);const[status,setStatus]=useState('idle');const[error,setError]=useState('');const thumbUrl=useMemo(()=>thumbnail&&Platform.OS==='web'?URL.createObjectURL(thumbnail):null,[thumbnail]);
 useEffect(()=>()=>{if(thumbUrl)URL.revokeObjectURL(thumbUrl)},[thumbUrl]);
 const field=(key,label,multiline=false)=><><Text style={styles.fieldLabel}>{label}</Text><TextInput accessibilityLabel={label} value={form[key]} onChangeText={value=>setForm(v=>({...v,[key]:value}))} multiline={multiline} style={multiline?styles.promptInput:styles.input} placeholderTextColor="#68727c"/></>;
 async function upload(){if(!user){onRequireAuth();return}if(!video||!form.title.trim()||!form.description.trim()||!form.aiDisclosure.trim()||!form.language.trim()||!form.category.trim()||!form.rights){setError('Complete every required field, choose a video, and confirm your rights.');return}setError('');setStatus('uploading');setProgress(0);try{const token=await tokenGet();const uploaded=await new Promise((resolve,reject)=>{const body=new FormData();Object.entries(form).forEach(([key,value])=>body.append(key,String(value)));body.append('video',video);if(thumbnail)body.append('thumbnail',thumbnail);const xhr=new XMLHttpRequest();xhr.open('POST',`${API_BASE}/api/content/upload`);xhr.setRequestHeader('Authorization',`Bearer ${token}`);xhr.upload.onprogress=e=>{if(e.lengthComputable)setProgress(Math.round(e.loaded/e.total*100))};xhr.onerror=()=>reject(new Error('Upload interrupted. Check your connection and retry.'));xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve(JSON.parse(xhr.responseText||'{}')):reject(new Error(xhr.status===401?'Sign in again to upload.':`Upload failed (${xhr.status}).`));xhr.send(body)});setStatus('processing');const contentId=uploaded.id||uploaded.content?.id||uploaded.data?.id;if(contentId){for(let attempt=0;attempt<8;attempt++){await new Promise(resolve=>setTimeout(resolve,1500));const check=playbackDecision(await api(`/api/content/${encodeURIComponent(contentId)}/playback`,{retries:0}));if(check.kind==='ready'){setStatus('ready');return}if(check.playback.mediaStatus==='failed')throw new Error('Video processing failed. You can retry the upload.')}}}catch(e){setError(e.message);setStatus('failed')}}
 return <View style={styles.promptLab}><View style={styles.promptHead}><View><Text style={styles.promptKicker}>SECURE VIDEO UPLOAD</Text><Text style={styles.promptTitle}>Publish a new title</Text></View><Text style={styles.beta}>{status==='idle'?'DRAFT':status.toUpperCase()}</Text></View>{!user?<View style={styles.apiBanner}><Text style={styles.apiText}>Authentication is required before any media can be uploaded.</Text><Button small onPress={onRequireAuth}>Sign in</Button></View>:null}{field('title','TITLE')}{field('description','DESCRIPTION',true)}{field('aiDisclosure','AI DISCLOSURE',true)}{field('language','LANGUAGE')}{field('category','CATEGORY')}<Text style={styles.fieldLabel}>VIDEO AND THUMBNAIL</Text>{Platform.OS==='web'?<View style={styles.uploadRow}><input aria-label="Video file" type="file" accept="video/mp4,application/vnd.apple.mpegurl" onChange={e=>setVideo(e.target.files?.[0]||null)}/><input aria-label="Thumbnail image" type="file" accept="image/*" onChange={e=>setThumbnail(e.target.files?.[0]||null)}/></View>:<Text style={styles.sub}>Uploads are currently available in Ripple Studio on the web.</Text>}{thumbUrl?<img src={thumbUrl} alt="Thumbnail preview" style={{width:240,maxWidth:'100%',aspectRatio:'16 / 9',objectFit:'cover',marginTop:12,borderRadius:8}}/>:null}<Pressable accessibilityRole="checkbox" accessibilityState={{checked:form.rights}} onPress={()=>setForm(v=>({...v,rights:!v.rights}))} style={styles.rightsRow}><Text style={styles.pillText}>{form.rights?'☑':'☐'} I confirm I own or license all rights to this upload.</Text></Pressable>{status==='uploading'?<View accessibilityLiveRegion="polite"><Text style={styles.playerStatusText}>Uploading… {progress}%</Text><View style={styles.progressTrack}><View style={[styles.progressFill,{width:`${progress}%`}]}/></View></View>:null}{status==='processing'?<Text accessibilityLiveRegion="polite" style={styles.playerStatusText}>Upload complete. Ripple is processing your video; its status will update to ready or failed after backend processing.</Text>:null}{status==='ready'?<Text accessibilityLiveRegion="polite" style={styles.playerStatusText}>Your video is ready for playback.</Text>:null}{error?<Text accessibilityRole="alert" style={styles.error}>{error}</Text>:null}<Button onPress={upload} disabled={status==='uploading'}>{status==='failed'?'Retry upload':status==='uploading'?'Uploading…':'Upload securely'}</Button></View>
}

function RippleApp(){
 const {width,height}=useWindowDimensions(); const responsive=getResponsiveState(width); const {compactPhone,phone,tablet,desktop,wideDesktop}=responsive; const bottomNavigation=phone||tablet;
 const[screen,setScreen]=useState('home');const[backend,setBackend]=useState([]);const[creators,setCreators]=useState([]);const[user,setUser]=useState(null);const[myList,setMyList]=useState([]);const[auth,setAuth]=useState(false);const[player,setPlayer]=useState(null);const[playNotice,setPlayNotice]=useState(null);const[loading,setLoading]=useState(true);const[apiError,setApiError]=useState('');const[filter,setFilter]=useState('all');const[query,setQuery]=useState('');const[prompt,setPrompt]=useState('A forgotten observatory maps a celestial river above an ancient kingdom.');const[enhanced,setEnhanced]=useState('');const[heroIndex,setHeroIndex]=useState(0);
 const load=useCallback(async()=>{setLoading(true);setApiError('');try{const [healthResult,contentResult,creatorResult]=await Promise.allSettled([api('/health',{retries:1}),api('/api/content'),api('/api/creators')]);if(healthResult.status==='rejected')throw healthResult.reason;if(contentResult.status==='rejected')throw contentResult.reason;setBackend(extractList(contentResult.value,'content').map(normalizeItem));if(creatorResult.status==='fulfilled')setCreators(extractList(creatorResult.value,'creators'));const t=await tokenGet();if(t){try{const [me,list]=await Promise.all([api('/api/me'),api('/api/my-list')]);setUser(me.user||me);setMyList(extractList(list,'items'))}catch(e){if(e.status===401){await tokenSet(null);setUser(null)}else throw e}}}catch(e){setApiError(e.message||'Ripple could not reach the service.');setBackend([])}finally{setLoading(false)}},[]);useEffect(()=>{load()},[load]);
 const saved=useMemo(()=>new Set(myList.map(x=>x.title)),[myList]);
 const editorialRails=useMemo(()=>CATEGORY_CONFIG.map(config=>({config,items:backend.filter(item=>getEditorialRail(item,config))})).filter(rail=>rail.items.length),[backend]);
 function resolve(x){return resolveContent(x,backend)}
 async function play(x){const selected=resolve(x);if(selected.isEditorialPreview||!selected.backendContentId){setPlayNotice({kind:'pending',title:selected.title});return}setPlayNotice({kind:'loading',title:selected.title});try{const id=encodeURIComponent(selected.backendContentId);const [detail,playbackPayload]=await Promise.all([api(`/api/content/${id}`),api(`/api/content/${id}/playback`)]);const decision=playbackDecision(playbackPayload);if(decision.kind!=='ready'){setPlayNotice({kind:decision.kind,title:selected.title});return}const details=detail?.content||detail?.data||detail;setPlayNotice(null);setPlayer({...selected,...details,...decision.playback,image:selected.image,backendContentId:selected.backendContentId,isPlayable:true})}catch(e){setPlayNotice({kind:'network',title:selected.title,message:e.message})}}
 async function toggle(x){if(!user)return setAuth(true);const b=backend.find(i=>i.id===x.id)||backend.find(i=>String(i.title).toLowerCase()===x.title.toLowerCase());if(!b)return;try{if(saved.has(b.title)){await api(`/api/my-list/${b.id}`,{method:'DELETE'});setMyList(v=>v.filter(i=>i.id!==b.id))}else{await api(`/api/my-list/${b.id}`,{method:'PUT'});setMyList(v=>[b,...v])}}catch(e){setApiError(e.message)}}
 async function action(kind,item){if(kind==='share'&&Platform.OS==='web'){if(globalThis.navigator?.share)return globalThis.navigator.share({title:item.title,url:globalThis.location.href});return globalThis.navigator?.clipboard?.writeText(globalThis.location.href)}if(!user)return setAuth(true);const route=kind==='follow'?`/api/creators/${item.id}/follow`:kind==='report'?`/api/content/${item.backendContentId||item.id}/reports`:`/api/content/${item.backendContentId||item.id}/${kind==='like'?'likes':'comments'}`;try{await api(route,{method:kind==='comments'?'GET':'POST'})}catch(e){setApiError(e.message)}}
 async function progress(item,value){if(!user||!item.backendContentId)return;try{await api(`/api/content/${item.backendContentId}/progress`,{method:'PUT',body:JSON.stringify({progress:value})})}catch{}}
 async function logout(){await tokenSet(null);setUser(null);setMyList([])}
 const fallback=ALL;const catalog=backend.length?backend:fallback;const show=catalog.filter(x=>(filter==='all'||x.type===filter)&&(!query||`${x.title} ${creatorName(x)}`.toLowerCase().includes(query.toLowerCase())));
 const heroes=useMemo(()=>selectHeroes(backend,HEROES),[backend]);const hero=resolve(heroes[heroIndex%heroes.length]);
 const moveHero=useCallback(direction=>setHeroIndex(current=>(current+direction+heroes.length)%heroes.length),[heroes.length]);
 useEffect(()=>{if(screen!=='home'||player)return undefined;const timer=setInterval(()=>moveHero(1),6500);return()=>clearInterval(timer)},[screen,player,moveHero]);

 const Header=()=> <View style={[styles.header,bottomNavigation&&styles.headerMobile,tablet&&styles.headerTablet]}><Pressable onPress={()=>setScreen('home')}><Logo/></Pressable>{desktop?<View style={styles.nav}>{[['home','Discover'],['browse','Browse'],['creators','Creators'],['studio','Creator Studio']].map(([k,l])=><Pressable key={k} onPress={()=>setScreen(k)} style={styles.navItem}><Text style={[styles.navText,screen===k&&styles.navActive]}>{l}</Text>{screen===k?<View style={styles.underline}/>:null}</Pressable>)}</View>:<View style={{flex:1}}/>}<View style={styles.actions}>{desktop?<Pressable onPress={()=>setScreen('browse')}><Text style={styles.search}>⌕</Text></Pressable>:null}{user?<Button small outline onPress={logout}>Logout</Button>:<Button small outline onPress={()=>setAuth(true)}>Sign in</Button>}</View></View>;

 const Home=()=> <ScrollView style={styles.page} showsVerticalScrollIndicator={false}>
   <View style={[styles.hero,phone&&styles.heroMobile,tablet&&styles.heroTablet,compactPhone&&styles.heroCompact]}><Image key={hero.id} source={hero.image} style={[styles.heroArt,phone&&styles.heroArtMobile,tablet&&styles.heroArtTablet]} resizeMode="cover"/><LinearGradient colors={bottomNavigation?['rgba(2,7,11,.1)','rgba(2,7,11,.55)',C.bg]:['#02070b','rgba(2,7,11,.82)','rgba(2,7,11,.08)']} start={bottomNavigation?{x:.5,y:0}:{x:0,y:.5}} end={bottomNavigation?{x:.5,y:1}:{x:1,y:.5}} style={StyleSheet.absoluteFillObject}/><LinearGradient colors={['transparent','transparent',C.bg]} style={StyleSheet.absoluteFillObject}/>
    <Pressable accessibilityRole="button" accessibilityLabel="Previous featured title" onPress={()=>moveHero(-1)} style={[styles.heroArrow,styles.arrowLeft,phone&&styles.heroArrowMobile]}><Text style={styles.arrowText}>‹</Text></Pressable><Pressable accessibilityRole="button" accessibilityLabel="Next featured title" onPress={()=>moveHero(1)} style={[styles.heroArrow,styles.arrowRight,phone&&styles.heroArrowMobile]}><Text style={styles.arrowText}>›</Text></Pressable>
    <View style={[styles.heroCopy,phone&&styles.heroCopyMobile,tablet&&styles.heroCopyTablet,compactPhone&&styles.heroCopyCompact]}><View style={styles.livePill}><View style={styles.liveDot}/><Text style={styles.eyebrow}>{hero.eyebrow||'RIPPLE FEATURED'}</Text></View><Text style={[styles.heroTitle,phone&&styles.heroTitleMobile]}>{hero.title}</Text><Text style={[styles.heroDesc,phone&&styles.heroDescMobile]}>{hero.description||'Discover an original creation from an independent AI artist.'}</Text><View style={styles.heroMeta}>{hero.duration?<Text style={styles.metaLight}>{hero.duration}</Text>:null}</View><View style={styles.heroBtns}><Button onPress={()=>play(hero)}>{hero.isPlayable===true?'▶  Watch now':hero.isEditorialPreview?'Coming soon':'View details'}</Button><Button outline onPress={()=>toggle(hero)}>＋  My List</Button></View></View>
    <View style={[styles.dots,phone&&styles.dotsMobile]}>{heroes.map((item,index)=><Pressable key={item.id} accessibilityRole="button" accessibilityLabel={`Show featured title ${index+1}`} onPress={()=>setHeroIndex(index)} hitSlop={8}><View style={index===heroIndex?styles.dotOn:styles.dot}/></Pressable>)}</View>
   </View>
   <View style={[styles.container,bottomNavigation&&styles.containerMobile,wideDesktop&&styles.containerWide]}>
    {apiError?<View accessibilityRole="alert" style={styles.apiBanner}><View style={{flex:1}}><Text style={styles.apiTitle}>{API_BASE?'Service temporarily unavailable':'Configuration required'}</Text><Text style={styles.apiText}>{apiError} {catalog.length?'Showing the curated editorial preview.':''}</Text></View><Button small outline onPress={load}>Retry</Button></View>:null}
    <View style={styles.proofBar}><Text style={styles.proofLead}>THE NEW HOME OF AI IMAGINATION</Text><Text style={styles.apiText}>{backend.length?'Live catalogue':'EDITORIAL PREVIEW'}</Text></View>
    <View style={styles.sectionHead}><View><Text style={styles.trendingLabel}>Stories flowing beyond imagination</Text><Text style={styles.sub}>Ancient stories. Infinite new worlds.</Text></View><Pressable onPress={()=>setScreen('browse')}><Text style={styles.viewAll}>View all  ›</Text></Pressable></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.row}>{catalog.slice(0,5).map(x=><TrendingCard key={x.id} x={{...x,color:C.cyan,type:String(x.type).toUpperCase()}} onPlay={play}/>)}</ScrollView>
    <View style={styles.exploreTop}><Text style={styles.exploreTitle}>Explore by Category</Text><View style={styles.sort}><Text style={styles.sortText}>Sort: Popular　⌄</Text></View></View><View style={styles.pills}>{[['all','All'],['film','Cinematic Films'],['short','Short Form'],['music','AI Music Videos'],['art','Generative Art']].map(([k,l])=><Pressable key={k} onPress={()=>setFilter(k)} style={[styles.pill,filter===k&&styles.pillOn]}><Text style={styles.pillText}>{l}</Text></Pressable>)}</View>
    {editorialRails.map(({config,items},index)=><Section key={config.title} title={config.title} icon={index%3===0?'✦':index%3===1?'◉':'⌁'} items={items} onPlay={play} onToggle={toggle} saved={saved} onViewAll={()=>setScreen('browse')}/>) }
    <View style={styles.studioBanner}><LinearGradient colors={['rgba(239,147,104,.17)','rgba(33,215,232,.05)']} start={{x:0,y:0}} end={{x:1,y:1}} style={StyleSheet.absoluteFillObject}/><View style={styles.studioCopy}><Text style={styles.eyebrow}>BUILT FOR AI STORYTELLERS</Text><Text style={styles.studioTitle}>Where ancient imagination meets generative technology</Text><Text style={styles.studioText}>Transform an idea into a cinematic world. Develop culturally grounded prompts, plan scenes, create sound, disclose AI tools and publish responsibly.</Text></View><Button onPress={()=>setScreen('studio')}>Create your first world</Button></View>
    <View style={styles.cta}><View style={styles.ctaLeft}><View style={styles.ctaLogo}><Text style={styles.logoMark}>R</Text></View><View><Text style={styles.ctaTitle}>Ripple is a home for original AI cinema</Text><Text style={styles.ctaText}>Ripple is a home for original AI cinema, mythology-inspired storytelling and independent creators.</Text></View></View>{!user?<Button outline onPress={()=>setAuth(true)}>Create an account</Button>:null}</View>
   </View>
  </ScrollView>;

 const Browse=()=> <ScrollView style={styles.page} contentContainerStyle={[styles.inner,bottomNavigation&&styles.innerMobile,wideDesktop&&styles.innerWide]}><Text style={styles.pageTitle}>Browse Ripple</Text><TextInput accessibilityLabel="Search titles or creators" value={query} onChangeText={setQuery} placeholder="Search titles or creators" placeholderTextColor="#8c96a0" style={styles.input}/><View style={styles.pills}>{[['all','All'],['film','Films'],['short','Shorts'],['music','Music'],['art','Art']].map(([k,l])=><Pressable accessibilityRole="button" key={k} onPress={()=>setFilter(k)} style={[styles.pill,filter===k&&styles.pillOn]}><Text style={styles.pillText}>{l}</Text></Pressable>)}</View>{show.length?<View style={styles.grid}>{show.map(x=><MediaCard key={x.id} x={x} onPlay={play} onToggle={toggle} saved={saved.has(x.title)} style={phone?styles.mediaCardMobile:tablet?styles.mediaCardTablet:null}/>)}</View>:<View style={styles.empty}><Text style={styles.playerStatusTitle}>Nothing found</Text><Text style={styles.sub}>Try another search or category.</Text></View>}</ScrollView>;
 const Creators=()=> <ScrollView style={styles.page} contentContainerStyle={[styles.inner,bottomNavigation&&styles.innerMobile,wideDesktop&&styles.innerWide]}><Text style={styles.pageTitle}>AI Creators</Text><Text style={styles.sub}>Meet the artists behind Ripple's films, shorts, music and generative worlds.</Text>{creators.length?<View style={styles.creatorGrid}>{creators.map((creator,i)=>{const n=creator.name||creator.displayName||creator.username||'Creator';return <View key={creator.id||n} style={[styles.creatorCard,phone&&styles.creatorCardMobile,tablet&&styles.creatorCardTablet]}><Image source={creator.bannerUrl?{uri:creator.bannerUrl}:A.hero} style={styles.creatorBanner}/><View style={styles.avatar}><Text style={styles.avatarText}>{n[0]}</Text></View><Text style={styles.creatorName}>{n}</Text><Text style={styles.creatorHandle}>@{creator.handle||creator.username||n.toLowerCase().replaceAll(' ','')}</Text><Text style={styles.sub}>{creator.bio||'Independent AI creator.'}</Text><Button small outline onPress={()=>action('follow',creator)}>Follow</Button></View>})}</View>:<View style={styles.empty}><Text style={styles.sub}>{apiError?'Creator profiles will return when the service is available.':'No creator profiles have been published yet.'}</Text><Button small outline onPress={load}>Retry</Button></View>}</ScrollView>;
 const List=()=> <ScrollView style={styles.page} contentContainerStyle={[styles.inner,bottomNavigation&&styles.innerMobile,wideDesktop&&styles.innerWide]}><Text style={styles.pageTitle}>My List</Text>{!user?<View style={styles.empty}><Text style={styles.sub}>Sign in to save your favorite Ripple creations.</Text><Button onPress={()=>setAuth(true)}>Sign in</Button></View>:myList.length?<View style={styles.grid}>{myList.map((b,i)=><MediaCard key={b.id} x={{...ALL[i%ALL.length],...b,image:ALL.find(x=>x.title===b.title)?.image||ALL[i%ALL.length].image,creator:b.creator?.name||ALL[i%ALL.length].creator}} onPlay={setPlayer} onToggle={toggle} saved style={phone?styles.mediaCardMobile:tablet?styles.mediaCardTablet:null}/>)}</View>:<Text style={styles.sub}>Your list is empty.</Text>}</ScrollView>;

 const Studio=()=> <ScrollView style={styles.page} contentContainerStyle={[styles.inner,bottomNavigation&&styles.innerMobile,wideDesktop&&styles.innerWide]}><View style={styles.studioHero}><View style={{flex:1}}><Text style={styles.eyebrow}>RIPPLE CREATOR STUDIO · BETA</Text><Text style={[styles.pageTitle,{marginTop:10,marginBottom:10}]}>Build your next cinematic world.</Text><Text style={styles.studioText}>Transform an idea into a cinematic world. Develop culturally grounded prompts, plan scenes, create sound, disclose AI tools and publish responsibly.</Text></View><View style={styles.projectBadge}><Text style={styles.projectBadgeTop}>CURRENT PROJECT</Text><Text style={styles.projectBadgeTitle}>Untitled mythology-inspired project</Text><Text style={styles.projectBadgeMeta}>Draft · Saved locally only</Text></View></View><View style={styles.toolGrid}>{TOOLKIT.map((t,i)=><Pressable key={t.title} onPress={()=>i===0?null:setEnhanced(`${t.title} is ready for your next project.`)} style={({hovered})=>[styles.toolCard,hovered&&styles.toolHover]}><View style={[styles.toolIcon,{borderColor:t.accent}]}><Text style={[styles.toolIconText,{color:t.accent}]}>{t.icon}</Text></View><Text style={styles.toolTitle}>{t.title}</Text><Text style={styles.toolText}>{t.text}</Text><Text style={[styles.toolLink,{color:t.accent}]}>Open tool  →</Text></Pressable>)}</View><View style={[styles.promptLab,bottomNavigation&&{padding:20}]}><View style={styles.promptHead}><View><Text style={styles.promptKicker}>PROMPT LAB</Text><Text style={styles.promptTitle}>Turn a spark into a scene</Text></View><Text style={styles.beta}>BETA</Text></View><Text style={styles.fieldLabel}>YOUR IDEA</Text><TextInput multiline value={prompt} onChangeText={setPrompt} placeholder="Describe your scene…" placeholderTextColor="#68727c" style={styles.promptInput}/><View style={styles.promptActions}><View style={styles.miniPills}><Text style={styles.miniPill}>Cinematic</Text><Text style={styles.miniPill}>16:9</Text><Text style={styles.miniPill}>Dreamlike</Text></View><Button onPress={()=>setEnhanced(`Cinematic wide shot: ${prompt} Volumetric light, deliberate camera movement, intricate environmental detail, dreamlike realism, copper and cyan color palette, 35mm film texture.`)}>✦  Enhance prompt</Button></View>{enhanced?<View style={styles.output}><Text style={styles.outputLabel}>ENHANCED PROMPT</Text><Text style={styles.outputText}>{enhanced}</Text></View>:null}</View><CreatorUpload user={user} onRequireAuth={()=>setAuth(true)}/><View style={styles.workflow}><Text style={styles.sectionTitle}>Your creative workflow</Text><View style={styles.workflowLine}>{['01  IDEA','02  STORYBOARD','03  CREATE','04  PUBLISH'].map((x,i)=><View key={x} style={styles.workflowStep}><Text style={styles.workflowNumber}>{x.split('  ')[0]}</Text><Text style={styles.workflowText}>{x.split('  ')[1]}</Text>{i<3?<View style={styles.connector}/>:null}</View>)}</View></View></ScrollView>;

 return <SafeAreaView style={styles.safe}><StatusBar barStyle="light-content" backgroundColor={C.bg}/><Header/>{loading&&backend.length===0?<View style={styles.loading}><View style={styles.skeleton}/><View style={styles.skeletonSmall}/><ActivityIndicator color={C.copper} size="large"/><Text style={styles.sub}>Loading Ripple…</Text></View>:screen==='home'?<Home/>:screen==='browse'?<Browse/>:screen==='creators'?<Creators/>:screen==='studio'?<Studio/>:<List/>}{bottomNavigation?<View style={styles.mobileNav}>{[['home','⌂','Home'],['browse','⌕','Browse'],['studio','✦','Create'],['list','＋','My List']].map(([k,icon,l])=><Pressable accessibilityRole="button" accessibilityLabel={l} key={k} onPress={()=>setScreen(k)} style={styles.mobileNavItem}><Text style={[styles.mobileIcon,screen===k&&{color:C.copper}]}>{icon}</Text><Text style={[styles.mobileText,screen===k&&{color:C.copper}]}>{l}</Text></Pressable>)}</View>:null}<PlaybackNotice notice={playNotice} onClose={()=>setPlayNotice(null)} onRetry={()=>{const item=backend.find(x=>x.title===playNotice?.title);if(item)play(item)}}/><AuthModal visible={auth} onClose={()=>setAuth(false)} onAuth={setUser}/><Player item={player} onClose={()=>setPlayer(null)} onProgress={progress} onAction={action}/></SafeAreaView>
}

export default function App(){return <AppErrorBoundary><RippleApp/></AppErrorBoundary>}

